function normalize(str) {
  return String(str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .trim();
}

function getTelegramContext(source) {
  const payload = source.payload || {};
  const message = source.message || payload.message || payload.body?.message || {};
  const chatId = source.chatId || message.chat?.id || payload.chatId || '';
  const rawText = String(source.rawText || source.text || message.text || message.caption || payload.text || '').trim();
  return { payload, message, chatId, rawText };
}

function cleanName(value) {
  return String(value || '')
    .trim()
    .replace(/^[\"'“”‘’]+|[\"'“”‘’]+$/g, '')
    .replace(/\s+/g, ' ');
}

const source = $('Execute Workflow Trigger').item.json || {};
const ctx = getTelegramContext(source);
const raw = ctx.rawText;
const text = normalize(raw);
const prefixes = ['them dong vao sheet', 'append row'];
let body = raw;
for (const prefix of prefixes) {
  if (text.startsWith(prefix + ' ')) {
    body = raw.slice(prefix.length + 1).trim();
    break;
  }
}

let spreadsheetId = source.spreadsheetId || source.sheetId || source.fileId || source.targetId || '';
let sheetName = cleanName(source.sheetName || source.fileName || '');
let rowData = String(source.rowData || source.content || '').trim();

if ((!sheetName || !rowData) && body.includes(':')) {
  const idx = body.indexOf(':');
  sheetName = sheetName || cleanName(body.slice(0, idx));
  rowData = rowData || body.slice(idx + 1).trim();
}

const values = rowData ? rowData.split(',').map((item) => item.trim()) : [];

return [{
  json: {
    ...source,
    payload: ctx.payload,
    message: ctx.message,
    chatId: ctx.chatId,
    rawText: raw,
    text,
    spreadsheetId,
    sheetName,
    rowData,
    values,
    hasTarget: Boolean(spreadsheetId || sheetName),
    hasContent: values.length > 0,
    response: (spreadsheetId || sheetName) && values.length ? '' : '📊 <b>Them dong vao Google Sheet</b>\n\nVi du: <code>them dong vao sheet Chi tieu: cafe,30000,an uong</code>'
  }
}];

const source = $('Prepare Action').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((item) => item.id || item.name);
if (!rows.length) {
  return [{ json: { ...source, spreadsheetId: '', response: 'Khong tim thay Google Sheet phu hop.' } }];
}
const sheet = rows[0];
return [{ json: { ...source, spreadsheetId: sheet.id || source.spreadsheetId || '', sheetName: sheet.name || source.sheetName || '', webViewLink: sheet.webViewLink || '' } }];

function escapeHtml(value = '') {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;');
}

const source = $('Prepare Action').item.json || {};
const sheetId = source.spreadsheetId || '';
const link = source.webViewLink || (sheetId ? `https://docs.google.com/spreadsheets/d/${sheetId}/edit` : '');

if (!source.chatId) {
  throw new Error('Missing chatId while formatting Google Sheets append response.');
}

let text = '✅ <b>Da them dong vao Google Sheet</b>\n\n';
text += `<b>${escapeHtml(source.sheetName || 'Khong ro ten')}</b>\n`;
if (sheetId) text += `ID: <code>${escapeHtml(sheetId)}</code>\n`;
text += `So cot da them: ${source.values.length}\n`;
if (link) text += `🔗 <a href="${escapeHtml(link)}">Mo bang tinh</a>`;

return [{ json: { chatId: source.chatId, text: text.trim() } }];
